const assert = require('node:assert/strict');
const { Ledger } = require('../.build/ledger');
const { PaymentService } = require('../.build/service');
const { Transient } = require('../.build/transport');

async function main() {
  // Retry after debit committed: one debit, same receipt forwarded each time.
  {
    const ledger = new Ledger(); const seen = []; let fails = 2;
    const svc = new PaymentService(ledger, { acknowledge: async r => { seen.push(r); if (fails-- > 0) throw new Transient('t'); } });
    const r = await svc.pay('t1', 'k', 50, 3);
    assert.equal(ledger.entries.length, 1); assert.equal(seen.length, 3);
    assert.ok(seen.every(x => x === r));
  }
  // Exhausted retries preserve the final exception.
  {
    const ledger = new Ledger(); let n = 0; const errs = [];
    const svc = new PaymentService(ledger, { acknowledge: async () => { const e = new Transient('t' + ++n); errs.push(e); throw e; } });
    await assert.rejects(svc.pay('t1', 'k', 50, 2), e => e === errs[1]);
    assert.equal(n, 2); assert.equal(ledger.entries.length, 1);
    // Retry of the same payment: no new debit, same receipt.
    await assert.rejects(svc.pay('t1', 'k', 50, 1), Transient);
    assert.equal(ledger.entries.length, 1);
  }
  // Non-transient errors are not retried.
  {
    const ledger = new Ledger(); let n = 0; const boom = new Error('boom');
    const svc = new PaymentService(ledger, { acknowledge: async () => { n++; throw boom; } });
    await assert.rejects(svc.pay('t', 'k', 1, 5), e => e === boom);
    assert.equal(n, 1);
  }
  // Repeated equal amount returns original; conflict throws without debit; tenant scoping.
  {
    const ledger = new Ledger(); const acks = [];
    const svc = new PaymentService(ledger, { acknowledge: async r => { acks.push(r); } });
    const a = await svc.pay('t1', 'k', 10);
    assert.equal(await svc.pay('t1', 'k', 10), a);
    await assert.rejects(svc.pay('t1', 'k', 11), /^Error: key conflict$/);
    assert.equal(ledger.entries.length, 1); assert.equal(acks.length, 2);
    const b = await svc.pay('t2', 'k', 10);
    assert.notEqual(b, a); assert.equal(ledger.entries.length, 2);
    // No separator collision.
    await svc.pay('a:b', 'c', 1); await svc.pay('a', 'b:c', 2);
    assert.equal(ledger.entries.length, 4);
  }
  // Concurrent calls.
  {
    const ledger = new Ledger();
    const svc = new PaymentService(ledger, { acknowledge: async () => { await new Promise(r => setTimeout(r, 5)); } });
    const rs = await Promise.all([1, 2, 3, 4].map(() => svc.pay('t', 'k', 7)));
    assert.equal(ledger.entries.length, 1); assert.ok(rs.every(r => r === rs[0]));
    const mixed = await Promise.allSettled([svc.pay('t', 'z', 1), svc.pay('t', 'z', 2)]);
    assert.equal(mixed.filter(x => x.status === 'fulfilled').length, 1);
    assert.equal(ledger.entries.length, 2);
  }
  // Validation before any ledger/transport action.
  {
    const ledger = new Ledger(); let acks = 0;
    const svc = new PaymentService(ledger, { acknowledge: async () => { acks++; } });
    const bad = [['', 'k', 1], ['t', '', 1], ['t', 'k', 0], ['t', 'k', -1], ['t', 'k', 1.5], ['t', 'k', NaN],
      ['t', 'k', '5'], [undefined, 'k', 1], ['t', 'k', 1, 0], ['t', 'k', 1, 6], ['t', 'k', 1, 2.5], ['t', 'k', 1, NaN]];
    for (const args of bad) await assert.rejects(svc.pay(...args), /^Error: invalid payment$/);
    assert.equal(ledger.entries.length, 0); assert.equal(acks, 0);
    await svc.pay('t', 'k', 1, 1); await svc.pay('t', 'k2', 1, 5);
  }
}
module.exports = main();

